DATA.politics['人民代表大会制度'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'政治与法治体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'人民代表大会制度为什么是根本政治制度？' },
  { lead:false,text:'①从地位看：人民代表大会制度是我国的根本政治制度，是我国的政体，直接体现我国人民民主专政的国体，在我国政治制度体系中居于核心地位，国家的其他制度都由它产生、受它制约。' },
  { lead:false,text:'②从体系看：我国的国家权力机关是人民代表大会，包括全国人民代表大会和地方各级人民代表大会。全国人民代表大会是最高国家权力机关，行使最高立法权、最高决定权、最高任免权、最高监督权。' },
  { lead:false,text:'③从职权看：立法权——制定、修改、废止法律；决定权——决定国家重大事项（审查批准国民经济和社会发展计划、批准预算）；任免权——选举、决定、任免国家机关领导人员；监督权——监督“一府一委两院”的工作。' },
  { lead:false,text:'④从代表看：人大代表由民主选举产生，是国家权力机关的组成人员，享有审议权、表决权、提案权、质询权，并负有模范遵守宪法法律、密切联系群众、自觉接受人民监督的义务。' },
  { lead:false,text:'⑤从原则看：人民代表大会制度实行民主集中制原则，即在民主基础上的集中和集中指导下的民主相结合。' },
  { lead:false,text:'⑥从意义看：这一制度保障了人民当家作主，动员了全体人民投身社会主义建设，保证了国家机关协调高效运转，维护了国家统一和民族团结。' },
  { lead:false,text:'⚠️ 易错点：<br>- 人民代表大会制度是我国的根本制度❌（根本制度是社会主义制度，人民代表大会制度是根本政治制度）<br>- 全国人大行使全部国家权力❌（行政机关、监察机关、司法机关依法行使相应职权）<br>- 人大与“一府一委两院”是领导与被领导关系❌（是产生与负责、监督与被监督关系）<br>备考提示：本考点常与“根本制度”“基本政治制度”辨析结合考查。答题时注意：①地位表述——人民代表大会制度是我国的根本政治制度，是人民当家作主的根本途径和最高实现形式；②职权辨析——立法、决定、任免、监督四项职权按对象区分；③民主集中制三组关系（人民与人大、人大与其他国家机关、中央与地方）要准确对应。易错提醒：人大是权力机关不是执行机关；全国人大行使“最高”职权，地方人大行使地方职权。复习时结合“一府一委两院”的产生与监督关系理解人大地位。' }
  ],
  cards:[
  ['1','全国人民代表大会与地方各级人民代表大会，构成怎样的国家权力机关体系？','人民通过民主选举产生人大代表，组成各级人民代表大会，代表人民统一行使国家权力。全国人民代表大会是最高国家权力机关，在我国国家机构中居于最高地位；地方各级人民代表大会是地方国家权力机关，决定本行政区域内的重大事项。人大与其他国家机关构成“产生—负责—监督”的关系，体现国家一切权力属于人民。','- “人大是执行机关”❌（是权力机关，执行机关是政府）\n-  “人大代表与人民是雇佣关系”❌（是代表与被代表、监督与被监督的关系）\n延伸考点：全国人大常委会是全国人大的常设机关，在全国人大闭会期间行使部分职权，它向全国人大负责并报告工作。全国人大常委会行使立法权等职权。','政治与法治'],
  ['2','为什么我国不搞西方的“三权分立”和议会制，而要实行人民代表大会制度？','国体决定政体。我国是人民民主专政的社会主义国家，国家一切权力属于人民。人民代表大会制度植根于中国历史文化传统和革命建设实践，能够保证人民当家作主，避免“三权分立”带来的相互掣肘、议而不决、效率低下。实践证明，这一制度是适合中国国情的好制度，坚持和完善人民代表大会制度，是发展全过程人民民主的必然要求。','- “政体可以脱离国体随意移植”❌\n-  “三权分立更民主”❌（我国制度更适合国情，是人民的选择）\n答题要点：国体决定政体，政体体现国体；制度选择必须立足本国国情，不能照搬照抄。适合国情的制度才是好制度。','政治与法治'],
  ['3','人大行使的立法权、决定权、任免权、监督权，在考试中如何准确区分？','立法权：制定、修改、废止法律（对象是法律案）；决定权：审查批准重大事项（国民经济和社会发展计划、预算、重大工程立项）；任免权：选举、决定、任免国家机关领导人员（对象是人事）；监督权：听取审议工作报告、开展执法检查、提出质询（对象是“一府一委两院”的工作）。记忆口诀：法律—人事—大事—监督，分别对应立法、任免、决定、监督。','- “批准预算属于立法权”❌（决定权）\n-  “人事任命属于决定权”❌（任免权）\n-  “人大监督等于干预政府日常工作”❌（是法定监督，不代替行政权）\n近年等级考常以“通过法律”“批准预算”“人事任免”等表述设置干扰项，务必按对象归类。','政治与法治'],
  ['4','有人说人大代表只是“开会举举手”——人大代表究竟有哪些权利与义务？','人大代表是国家权力机关的组成人员，由人民选举产生，肩负人民重托。权利：审议权（审议各项议案和报告）、表决权（参加表决）、提案权（依法联名提出议案）、质询权（依法对政府等机关提出质询并要求答复）。义务：模范遵守宪法法律，密切联系群众，听取和反映人民群众的意见和要求，努力为人民服务，自觉接受人民监督。','- “人大代表可以凌驾于法律之上”❌\n-  “人大代表的提案就是法律”❌（议案需经人大审议通过才成法律）\n-  “代表个人意见可以代替人大决定”❌\n代表联络站、基层立法联系点等都是代表履职的重要平台，答题时可作事例引用。履职要求：为人民服务、对人民负责、受人民监督。','政治与法治'],
  ['5','民主集中制是我国国家机构的组织和活动原则，它在人民代表大会制度中怎样体现？','民主集中制的三个体现：①在人民与人大之间——人大代表由民主选举产生，对人民负责、受人民监督，体现“民主”；②在人大与其他国家机关之间——“一府一委两院”由人大产生，对它负责、受它监督，体现“集中”；③在中央与地方之间——在中央统一领导下，合理划分中央和地方的职权，充分发挥中央和地方两个积极性。','- “民主集中制就是少数服从多数”❌（还包括民主与集中相结合的完整制度安排）\n-  “地方与中央是完全对等的关系”❌（中央统一领导为前提）\n记忆口诀：人民选代表（民主），机关对人大负责（集中），中央统一领导地方（统一）。','政治与法治'],
  ['6','2018年宪法修正案经由全国人大表决通过——这一事件如何体现我国权力运行机制？','2018年3月，宪法修正案由第十三届全国人民代表大会第一次会议以全体代表的三分之二以上多数表决通过。这体现：全国人民代表大会是最高国家权力机关，行使最高立法权（修改宪法）；修宪过程经过广泛征求意见、充分审议，体现科学立法、民主立法、依法立法；把党和人民的意志通过法定程序转化为国家意志。','- “宪法由全国人大常委会修改”❌（仅全国人大有权修改宪法）\n-  “修宪程序与普通法律相同”❌（宪法修改程序更为严格）\n延伸：法律草案公开征求意见、基层立法联系点，都是民主立法、科学立法、依法立法的体现。这一程序保障人民意志转化为国家意志。','政治与法治']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'我国的根本政治制度是（　）\nA. 人民代表大会制度　B. 多党合作和政治协商制度　C. 民族区域自治制度　D. 基层群众自治制度', ans:'A。人民代表大会制度是我国的根本政治制度，其余三项是基本政治制度。' },
  { type:'配对 · 职权对应', body:'将人大职权与实例配对：① 表决通过民法典　② 审查批准年度中央预算　③ 听取审议国务院工作报告　④ 选举国家主席\nA. 立法权　B. 决定权　C. 监督权　D. 任免权', ans:'①-A　②-B　③-C　④-D' },
  { type:'图表排序 · 流程判断', body:'按我国国家权力运行的流程排序：① 人民通过选举产生人大代表　② 人大代表组成各级人民代表大会　③ 人民代表大会产生“一府一委两院”　④ “一府一委两院”对人大负责、受人大监督', ans:'①→②→③→④。这一流程体现人民当家作主和民主集中制原则。' },
  { type:'材料解析 · 说明＋论证', body:'材料：习近平在中央人大工作会议上指出，人民代表大会制度是“符合我国国情和实际、体现社会主义国家性质、保证人民当家作主、保障实现中华民族伟大复兴的好制度”。\n问题：（1）为什么说人民代表大会制度是“好制度”？（4分）（2）结合所学，说明人大代表怎样密切联系群众。（4分）', ans:'（1）它保障了人民当家作主，动员了全体人民投身社会主义建设，保证了国家机关协调高效运转，维护了国家统一和民族团结（4分）。（2）人大代表应深入群众、听取和反映群众意见和要求，通过提案、质询等方式推动问题解决，自觉接受人民监督（4分）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'有人认为“人大代表就是开开会、举举手”。运用人民代表大会制度的知识，谈谈你的看法。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只提人大代表或人民代表大会其一，无关联。\n· 辩证两维（4~6分）：说明人大代表依法享有审议权、表决权、提案权、质询权，肩负反映民意、监督国家机关的重任，并非“举举手”。\n· 综合升华（7~8分）：落到“人民代表大会制度保障人民当家作主，完善这一制度需要代表尽责履职”的规律性认识。' }
  ]
};
DATA.politics['人民群众'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'哲学体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'\'人民，只有人民，才是创造世界历史的动力\'——毛泽东这句话，是历史唯物主义群众观的经典表达。' },
  { lead:false,text:'人民群众的含义：一切对社会历史起推动作用的人们——①量的规定：社会成员的大多数；②质的规定：对社会历史起推动作用。劳动群众是人民群众的主体部分（\'人民群众中最稳定的主体部分始终是从事物质资料生产的劳动群众\'）。' },
  { lead:false,text:'人民群众是历史的创造者（三表现）：<br>①物质财富的创造者——人民群众的生产活动是社会存在和发展的基础（\'一粥一饭，当思来处\'）；<br>②精神财富的创造者——人民群众的生活和实践是一切精神财富的源泉（《诗经》源于民间歌谣）；劳动群众还直接创造了精神财富（民间艺人）；<br>③社会变革的决定力量——人民群众是社会变革的主力军（\'水能载舟，亦能覆舟\'；新民主主义革命的胜利靠人民战争）。' },
  { lead:false,text:'方法论：<br>①群众观点——相信人民群众自己解放自己；全心全意为人民服务；一切向人民群众负责；虚心向人民群众学习；<br>②群众路线——一切为了群众，一切依靠群众，从群众中来，到群众中去（党的生命线和根本工作路线）。' },
  { lead:false,text:'反对英雄史观：历史唯心主义夸大个人作用，认为英雄创造历史——\'历史是群众的事业\'，杰出人物只有顺应人民意愿、依靠人民力量才能发挥作用。' },
  { lead:false,text:'\'江山就是人民，人民就是江山\'——群众史观是中国共产党的根本立场。<br>补充说明：本考点在近三年上海等级考中属高频内容，复习时务必结合案例与辨析要点。' }
  ],
  cards:[
  ['1','人民群众的内涵是什么？','人民群众内涵：一切对社会历史起推动作用的人们。两层规定：①量——社会成员的大多数；②质——对社会历史起推动作用（阻碍历史的反动势力不属于人民群众）。主体部分：从事物质资料生产的劳动群众。人民群众是历史范畴——不一并代内涵不同（今天：全体社会主义劳动者、建设者、爱国者）。','- \'人民群众就是劳动群众\'❌（主体是劳动群众，范围更广）\n-  \'人民群众包括反动分子\'❌（质的规定：推动历史者）','哲学'],
  ['2','人民群众怎样创造物质财富？','创造物质财富：①人民群众的生产活动是社会存在和发展的基础——衣食住行的物质条件都由劳动者创造（\'劳动创造了世界\'）；②劳动者是生产力的主导因素——劳动者的经验与技能推动生产力发展（从手工到智能制造的创新者）；③社会财富归根到底由劳动者创造——\'财富之父是劳动\'。\'没有人民的劳动，就没有一切\'。','- \'财富是企业家创造的\'❌（归根到底源于劳动者，企业家是组织者）\n-  \'科技精英独自创造财富\'❌（科技成果要靠劳动者转化为产品）','哲学'],
  ['3','人民群众怎样创造精神财富？','创造精神财富：①人民群众的生活和实践是一切精神财富形成和发展的源泉——（《诗经》\'饥者歌其食，劳者歌其事\'；《荷马史诗》源自民间传说）；②劳动群众还直接创造了精神财富——民间艺人、工匠（剪纸、泥塑、民歌）；③知识分子在群众实践中汲取营养、提炼升华（\'问渠那得清如许，为有源头活水来\'——群众生活是活水）。','- \'精神财富是天才创造的\'❌（源泉在群众实践）\n-  \'知识分子不属于人民群众\'❌（推动历史的知识分子属于人民群众）','哲学'],
  ['4','人民群众怎样决定社会变革？','社会变革的决定力量：①人民群众是社会变革的主力军——任何社会变革没有群众参与都不能成功（\'水能载舟，亦能覆舟\'）；②民心向背决定历史走向——\'得民心者得天下\'（秦亡汉兴、国民党败退与解放战争胜利）；③改革与革命都要依靠人民——\'人民群众是真正的铜墙铁壁\'。\'历史大势，源于民心\'。','- \'变革靠少数精英发动\'❌（精英只有动员群众才能成事）\n-  \'民心是无形的可以忽视\'❌（民心是决定力量）','哲学'],
  ['5','英雄史观错在哪里？','英雄史观（历史唯心主义）：认为历史是少数英雄人物创造的——\'英雄造时势\'。错误：①颠倒关系——不是英雄创造群众，而是群众孕育英雄（\'时势造英雄\'）；②忽视决定力量——英雄人物的作用以人民群众的实践为基础；③马克思主义观点——人民群众是历史的创造者，杰出人物只有顺应历史潮流、依靠人民才能起推动作用（\'英雄与群众：演员与舞台\'）。','- \'群众史观否定个人作用\'❌（承认杰出人物作用，但以群众为基础）\n-  \'英雄史观毫无合理之处\'❌（看到了个人作用，但夸大且颠倒）','哲学'],
  ['6','群众史观的规律性认识是什么？','规律总结：①人民创造历史——历史唯物主义的根本立场（区别于英雄史观）；②一切为了人民——价值取向（党的宗旨）；③一切依靠人民——力量源泉（群众路线）；④从群众中来到群众中去——工作方法（民主集中制）。\'人民是历史的\'剧作者\'，也是\'剧中人\'\'。中国实践：全过程人民民主、新时代\'枫桥经验\'——群众史观的制度表达。','- \'群众路线是工作方法不是世界观\'❌（既是历史观又是方法论）\n-  \'为人民服务只是道德要求\'❌（是历史唯物主义的必然结论）','哲学']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'人民群众的主体部分是（　）\nA. 知识分子　B. 劳动群众　C. 杰出人物　D. 青年学生', ans:'B。人民群众的主体部分始终是从事物质资料生产的劳动群众。' },
  { type:'配对 · 时空定位', body:'将表述与原理配对：① 一粥一饭当思来处　② 民间歌谣是《诗经》源泉　③ 水能载舟亦能覆舟\nA. 物质财富创造者　B. 精神财富创造者　C. 社会变革决定力量', ans:'①-A　②-B　③-C' },
  { type:'图表排序 · 读图分析', body:'按群众路线工作流程排列：① 到群众中去　② 从群众中来　③ 形成决策意见', ans:'②→③→①。从群众中来（集中）→决策→到群众中去（贯彻检验）。' },
  { type:'材料解析 · 读图分析＋综合', body:'材料：脱贫攻坚战中，数百万干部深入基层驻村帮扶，依靠群众发展产业，最终近1亿农村贫困人口全部脱贫。\n问题：（1）从群众史观角度，分析脱贫攻坚为什么必须依靠群众。（3分）（2）\'驻村帮扶\'体现了什么工作方法？（3分）', ans:'（1）原因：人民群众是历史的创造者、是社会变革的决定力量——脱贫的主体是贫困群众自身，只有依靠群众才能激发内生动力（3分）。（2）体现了群众路线——从群众中来、到群众中去（深入基层、依靠群众、为了群众）（3分）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'\'江山就是人民，人民就是江山。\'结合群众史观，谈谈你的认识。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只谈群众观点或举一例。\n· 辩证两维（4~6分）：人民群众创造历史的三表现（物质、精神、变革）与群众观点群众路线，各举实例。\n· 综合升华（7~8分）：落到\'人民是历史的创造者——坚持群众路线是党和国家事业发展的根本保证\'的规律性认识。' }
  ]
};
DATA.politics['人类命运共同体'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'国际政治体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'\'世界怎么了、我们怎么办？\'——面对百年未有之大变局，中国给出的答案是：构建人类命运共同体。' },
  { lead:false,text:'提出与发展：<br>2013年，习近平主席在莫斯科国际关系学院演讲中首次提出；此后不断发展——从理念到行动，从双边到多边，从区域到全球。\'构建人类命运共同体\'多次写入联合国决议，成为国际共识。' },
  { lead:false,text:'核心内涵（\'五个世界\'）：<br>持久和平、普遍安全、共同繁荣、开放包容、清洁美丽——对应政治、安全、经济、文化、生态五大维度。' },
  { lead:false,text:'核心理念：<br>①合作共赢——摒弃零和博弈；<br>②共商共建共享——全球事务各国商量着办；<br>③正确义利观——\'义利相兼、以义为先\'。' },
  { lead:false,text:'实践平台：<br>①\'一带一路\'——互联互通、共同发展（150多个国家签署合作文件）；<br>②全球发展倡议（2021）——聚焦发展议程；<br>③全球安全倡议（2022）——\'共同、综合、合作、可持续的安全观\'；<br>④全球文明倡议（2023）——文明交流互鉴；<br>⑤全球治理参与——气候（巴黎协定）、抗疫（疫苗公共产品）、维和。' },
  { lead:false,text:'重大意义：<br>①顺应和平与发展的时代主题；<br>②为全球治理体系变革提供中国方案（\'人类命运共同体是人间正道\'）；<br>③彰显大国担当——为人类谋进步、为世界谋大同。' },
  { lead:false,text:'\'世界好，中国才能好；中国好，世界才更好\'——人类命运共同体，是回答时代之问的中国答案。<br>补充说明：本考点在近三年上海等级考中属高频内容，复习时务必结合案例与辨析要点。' }
  ],
  cards:[
  ['1','人类命运共同体理念为什么提出？','提出背景：①全球性挑战增多——气候变化、公共卫生、恐怖主义等非传统安全威胁，\'没有哪个国家能独自应对\'；②旧治理体系失灵——单边主义、保护主义抬头；③中国发展需要——与世界深度联结（\'中国离不开世界\'）；④大国责任担当——为人类进步贡献智慧。\'时代之问呼唤中国答案\'。','- \'共同体是中国主导世界的方案\'❌（共商共建共享，非主导）\n-  \'共同体否定国家利益\'❌（兼顾本国与他国合理关切）','国际政治'],
  ['2','\'五个世界\'的内涵是什么？','\'五个世界\'：①持久和平——对话协商化解分歧，反对强权；②普遍安全——共同、综合、合作、可持续的安全观；③共同繁荣——合作共赢，缩小南北差距；④开放包容——文明交流互鉴，反对文明冲突论；⑤清洁美丽——应对气候变化，共建地球生命共同体。五大维度对应政治、安全、经济、文化、生态——\'五位一体的世界愿景\'。','- \'五个世界只讲经济合作\'❌（五位一体全维度）\n-  \'清洁美丽是发达国家的事\'❌（共同但有区别的责任）','国际政治'],
  ['3','三大全球倡议是什么？','三大全球倡议：①全球发展倡议（2021年）——坚持发展优先、以人民为中心，对接联合国2030年可持续发展议程（\'不让任何国家掉队\'）；②全球安全倡议（2022年）——\'共同、综合、合作、可持续的安全观\'，走对话而不对抗之路；③全球文明倡议（2023年）——倡导尊重世界文明多样性，加强国际人文交流。三大倡议：发展是目标、安全是保障、文明是根基。','- \'安全倡议主张军事同盟\'❌（对话协商、不结盟）\n-  \'文明倡议要输出文明\'❌（交流互鉴，反对输出）','国际政治'],
  ['4','共商共建共享怎样落地？','共商共建共享的落地：①共商——全球事务各国商量（气候谈判、G20）；②共建——共同行动建设（\'一带一路\'项目合作）；③共享——成果惠及各方（发展红利）。配套机制：①多边平台（联合国、金砖、上合）；②资金机制（亚投行、丝路基金）；③规则建设（\'一带一路\'绿色投资原则）。\'从理念到机制，从机制到项目\'。','- \'共商共建共享是援助\'❌（平等合作，非施舍）\n-  \'共享就是平均分配\'❌（共享发展成果，尊重市场规则）','国际政治'],
  ['5','对共同体的质疑如何回应？','常见质疑与回应：①\'中国要主导世界\'？——不：共商共建共享，从不干涉内政；②\'债务陷阱\'？——不：合作项目经过平等协商、商业运作，为当地创造就业与税收（中老铁路盈利性良好）；③\'只是口号\'？——不：写入联合国决议、150多国签署一带一路文件、三大倡议获广泛支持；④\'与联合国体系冲突\'？——不：对接2030议程，维护联合国宪章宗旨。\'事实胜于雄辩，行动回答质疑\'。','- \'共同体是结盟\'❌（不结盟、不对抗、不针对第三方）\n-  \'共同体取代联合国\'❌（维护联合国权威，是补充完善）','国际政治'],
  ['6','人类命运共同体的规律性认识是什么？','规律总结：①理念与行动统一——从倡议到决议到项目，步步落地；②利益与道义统一——正确义利观（\'义利相兼、以义为先\'）；③中国与世界统一——\'世界好，中国才能好；中国好，世界才更好\'；④短期与长远统一——应对当下挑战与构建长远秩序结合。\'人类命运共同体，是人间正道\'。','- \'共同体一蹴而就\'❌（长期过程，久久为功）\n-  \'共同体只利中国\'❌（互利共赢，惠及各方）','国际政治']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'人类命运共同体理念首次提出于（　）\nA. 2008年　B. 2013年　C. 2017年　D. 2021年', ans:'B。2013年习近平主席在莫斯科国际关系学院演讲中首次提出。' },
  { type:'配对 · 时空定位', body:'将\'五个世界\'与维度配对：① 持久和平　② 普遍安全　③ 共同繁荣　④ 清洁美丽\nA. 政治　B. 安全　C. 经济　D. 生态', ans:'①-A　②-B　③-C　④-D' },
  { type:'图表排序 · 时序判断', body:'按提出时间先后排列三大全球倡议：① 全球安全倡议　② 全球发展倡议　③ 全球文明倡议', ans:'②→①→③。2021年→2022年→2023年。' },
  { type:'材料解析 · 读图分析＋综合', body:'材料：\'构建人类命运共同体\'已十多次写入联合国决议；全球发展倡议得到100多个国家和国际组织支持。\n问题：（1）为什么人类命运共同体理念能得到国际社会广泛认同？（3分）（2）举两例说明其实践路径。（3分）', ans:'（1）原因：顺应和平与发展的时代主题；契合各国共同利益；为全球治理提供合作共赢方案（3分）。（2）实践：共建\'一带一路\'；提出全球发展倡议；参与全球气候治理（巴黎协定）；提供抗疫公共产品（3分，答出两点即可）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'\'人类命运共同体是中国为世界开出的时代药方。\'结合所学，谈谈你的认识。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只谈理念内涵或一项实践。\n· 辩证两维（4~6分）：理念内涵（五个世界、共商共建共享）与实践平台（一带一路、三大倡议、全球治理），各举实例。\n· 综合升华（7~8分）：落到\'面对全球性挑战，合作共赢取代零和博弈——人类命运共同体是回答时代之问的中国方案\'的规律性认识。' }
  ]
};
DATA.politics['价值观与价值判断'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'哲学体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'人生的扣子从一开始就要扣好——价值观，是人生的第一粒扣子。' },
  { lead:false,text:'价值的含义：一事物所具有的能够满足主体需要的属性和功能——事物对主体的积极意义（\'有用之物有价值\'）。' },
  { lead:false,text:'人的价值：<br>①社会价值——个人对社会的责任和贡献（\'给予\'）；<br>②自我价值——社会对个人的尊重和满足（\'获得\'）；<br>③关系——人的真正价值在于对社会的责任和贡献：评价一个人价值的大小，就是看他为社会、为人民贡献了什么（\'贡献是价值的标尺\'）。' },
  { lead:false,text:'价值观的导向作用：<br>①对人们认识世界和改造世界的活动有导向作用（不同价值观对同一事物的评价不同、行动不同）；<br>②对人生道路的选择有导向作用（价值观是人生的重要向导）；<br>③先进的价值观促进发展（社会主义核心价值观——\'最大公约数\'）。' },
  { lead:false,text:'价值判断与价值选择：<br>①含义——价值判断（对事物能否满足主体需要及满足程度的判断）是价值选择的基础；<br>②标准——自觉遵循社会发展的客观规律（顺应历史潮流）；自觉站在最广大人民的立场上（人民立场是最高价值标准）；<br>③特征——价值判断和价值选择具有社会历史性（随时代变化）与主体差异性（因人而异——但不等于\'怎么都对\'）。' },
  { lead:false,text:'创造和实现人生价值：<br>①在劳动和奉献中创造价值（劳动是人的存在方式——\'劳动最光荣\'）；<br>②在个人与社会的统一中实现价值（社会提供的客观条件是前提）；<br>③在砥砺自我中走向成功——发挥主观能动性、提高个人素质、坚定理想信念。' },
  { lead:false,text:'\'人生的价值在于奉献\'——价值观的最终考题，是人生实践。<br>补充说明：本考点在近三年上海等级考中属高频内容，复习时务必结合案例与辨析要点。' }
  ],
  cards:[
  ['1','价值与价值观是什么？','价值：一事物所具有的能够满足主体需要的属性和功能（\'有用性\'——粮食能充饥、书籍能增智）。价值观：人们对事物价值的总的看法和根本观点（\'什么重要、什么值得\'）。价值观是社会意识——由社会存在决定，随时代变化（\'不一并代有不同的价值观\'）。\'价值观是人的精神内核\'。','- \'价值是客体本身固有的\'❌（是客体属性满足主体需要的关系）\n-  \'价值观有对错吗\'✅（有——是否顺应规律与人民利益）','哲学'],
  ['2','人的价值怎样理解？','人的价值：①社会价值——个人对社会的责任和贡献（\'给\'：劳动创造、服务奉献）；②自我价值——社会对个人的尊重和满足（\'得\'：报酬、荣誉、保障）；③关系——人的真正价值在于对社会的贡献：\'评价一个人的价值，主要看他的贡献\'。\'给予比获取更幸福\'（奉献的人生观）。','- \'自我价值就是自私\'❌（正当的自我价值是实现社会价值的条件）\n-  \'贡献与满足对立\'❌（社会尊重满足以贡献为基础）','哲学'],
  ['3','价值观有什么导向作用？','价值观导向作用：①对认识世界和改造世界有导向作用——价值观不同，对事物的评价和态度不同、行动方向不同（\'义利观决定行为\'：诚信经营vs假冒伪劣）；②对人生道路的选择有导向作用——价值观是人生的重要向导（\'人生的扣子\'）；③方法论——树立正确的价值观，作出正确的价值判断与选择。\'价值观如罗盘，方向对了才有远方\'。','- \'价值观只是观念不影响行动\'❌（导向作用巨大）\n-  \'价值观无对错\'❌（先进促进、落后阻碍）','哲学'],
  ['4','价值判断与价值选择的标准是什么？','价值判断：对事物能否满足主体需要及满足程度作出的判断（\'这个政策好\'）。价值选择：在价值判断基础上作出的选择（\'支持这个政策\'）。标准：①客观规律——自觉遵循社会发展的客观规律（\'顺应历史潮流\'）；②人民立场——自觉站在最广大人民的立场上（\'人民利益是最高价值标准\'）。特征：社会历史性（时代不同标准不同）、主体差异性（立场不同判断不同）。','- \'价值判断因人而异所以无所谓对错\'❌（有客观标准——规律与人民）\n-  \'人民立场与规律标准矛盾\'❌（人民利益与历史规律一致）','哲学'],
  ['5','怎样创造和实现人生价值？','实现人生价值三途径：①在劳动和奉献中创造价值——劳动是人的存在方式，积极投身于为人民服务的实践（\'劳动最光荣\'）；②在个人与社会的统一中实现价值——社会提供的客观条件是实现价值的前提（\'时势造英雄\'），个人在奉献社会中实现自我；③在砥砺自我中走向成功——充分发挥主观能动性、提高个人素质、坚定理想信念（\'打铁还需自身硬\'）。','- \'实现价值只需要个人奋斗\'❌（社会条件是前提）\n-  \'自我价值与社会价值对立\'❌（统一于奉献社会的实践）','哲学'],
  ['6','价值观的规律性认识是什么？','规律总结：①价值是关系的——主体需要与客体属性的统一；②贡献是根本的——人的价值在于奉献（奉献与索取的辩证）；③标准是客观的——规律与人民立场（反对价值相对主义）；④导向是重要的——价值观塑造人生（\'扣好扣子\'）。\'价值观是方向盘，方法论是发动机\'。','- \'价值相对主义（怎么都对）\'❌（客观标准存在）\n-  \'价值观与真理观无关\'❌（正确的价值观要符合规律与真理）','哲学']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'评价一个人价值大小的根本标准是（　）\nA. 获得了多少荣誉　B. 为社会和人民贡献了什么　C. 拥有多少财富　D. 地位有多高', ans:'B。人的真正价值在于对社会的责任和贡献——评价标准是贡献。' },
  { type:'配对 · 时空定位', body:'将概念与含义配对：① 社会价值　② 自我价值　③ 价值判断　④ 价值选择\nA. 对社会的贡献　B. 社会对个人的满足　C. 对价值的判断　D. 基于判断的选择', ans:'①-A　②-B　③-C　④-D' },
  { type:'图表排序 · 读图分析', body:'按价值判断与价值选择的逻辑排序：① 价值选择　② 价值判断　③ 价值观导向', ans:'③→②→①。价值观→判断→选择。' },
  { type:'材料解析 · 读图分析＋综合', body:'材料：张桂梅扎根山区教育40余年，帮助近2000名女孩走出大山，自己却一身病痛、生活清贫，她说\'只要还有一口气，就要站在讲台上\'。\n问题：（1）从人的价值角度，分析张桂梅的人生价值。（3分）（2）她的事迹对青年实现人生价值有何启示？（3分）', ans:'（1）分析：她在劳动和奉献中创造价值——对社会的贡献（帮助山区女孩）是她的社会价值，是价值的根本（3分）。（2）启示：在劳动奉献中创造价值；在个人与社会的统一中实现价值；坚定理想信念、砥砺自我（3分，答出两点即可）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'\'人生的价值在于奉献，而不在于索取。\'结合价值观理论，谈谈你的认识。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只谈奉献或索取之一。\n· 辩证两维（4~6分）：社会价值与自我价值的关系（贡献是根本、满足是条件）与价值观的导向作用，各举实例。\n· 综合升华（7~8分）：落到\'在劳动和奉献中创造价值——把个人价值融入社会价值，是正确价值观的必然结论\'的规律性认识。' }
  ]
};
DATA.politics['依法治国'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'全面依法治国体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'全面依法治国是坚持和发展中国特色社会主义的基本方略，是国家治理体系和治理能力现代化的重要内容。' },
  { lead:false,text:'【总目标】建设中国特色社会主义法治体系，建设社会主义法治国家。中国特色社会主义法治体系由五个子体系构成：完备的法律规范体系、高效的法治实施体系、严密的法治监督体系、有力的法治保障体系，以及完善的党内法规体系。' },
  { lead:false,text:'【基本方针】党的十八大提出“科学立法、严格执法、公正司法、全民守法”十六字方针：科学立法是前提，严格执法是关键，公正司法是防线，全民守法是基础——四者缺一不可，共同构成法治建设的基本格局。' },
  { lead:false,text:'【宪法地位】坚持依法治国首先要坚持依宪治国，坚持依法执政首先要坚持依宪执政。宪法是国家的根本法，具有最高的法律地位、法律权威、法律效力，一切法律、行政法规和地方性法规都不得同宪法相抵触。' },
  { lead:false,text:'【党的领导】党的领导是社会主义法治最根本的保证。社会主义法治必须坚持党的领导，党的领导必须依靠社会主义法治。依法治国是党领导人民治理国家的基本方式，党的主张通过法定程序成为国家意志。' },
  { lead:false,text:'【一体建设】坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设。法治国家是法治建设的目标，法治政府是建设法治国家的重点任务和主体工程，法治社会是构筑法治国家的基础。' },
  { lead:false,text:'【深刻革命】全面依法治国是国家治理的一场深刻革命：它推动国家治理从主要依靠政策转向主要依靠法治，是治理理念、治理方式、治理体系的全方位变革。' },
  { lead:false,text:'⚠️ 易错点：<br>- 总目标是“建设法治政府”❌（总目标是建设中国特色社会主义法治体系、建设社会主义法治国家）<br>- 依法治国就是“用法管老百姓”❌（依法治国的主体是党领导的人民，人民是依法治国的主体和力量源泉）<br>- 宪法与普通法律地位相同❌（宪法是国家的根本法，普通法律不得与宪法相抵触）<br>补充说明：复习时要把“总目标—总抓手—基本方针—一体建设”串成链条：总目标指引方向，中国特色社会主义法治体系是总抓手，十六字方针是基本要求，一体建设是推进路径。' }
  ],
  cards:[
  ['1','必修3高频考点自查：依法治国基本方略是怎样确立并写入宪法的？','依法治国基本方略的确立历程：1978年党的十一届三中全会提出“有法可依、有法必依、执法必严、违法必究”的法制建设方针；1997年党的十五大把依法治国确立为党领导人民治理国家的基本方略；1999年九届全国人大二次会议通过宪法修正案，将“中华人民共和国实行依法治国，建设社会主义法治国家”写入宪法；2014年党的十八届四中全会专题研究全面推进依法治国。依法治国基本方略入宪，标志着依法治国由党的主张上升为国家意志。','- “依法治国1999年才提出”❌（1997年十五大提出，1999年写入宪法）\n-  “依法治国只是政府的事”❌（是党领导人民治理国家的基本方式）','全面依法治国'],
  ['2','必修3高频考点自查：为什么说党的领导是社会主义法治最根本的保证？','党的领导是中国特色社会主义最本质的特征，是社会主义法治最根本的保证。从政治上看，依法治国必须坚持正确政治方向，这一方向由党的政治路线决定；从实践上看，全面依法治国的总目标、总抓手都由党中央统筹推进；从制度上看，宪法确认了中国共产党的领导地位。坚持党的领导，就要坚持党领导立法、保证执法、支持司法、带头守法，把依法治国基本方略同依法执政基本方式统一起来。','- “党的主张可以直接当法律用”❌（党的主张必须通过法定程序才能成为国家意志）\n-  “坚持党的领导会削弱法治”❌（二者一致，党必须依法执政）','全面依法治国'],
  ['3','必修3高频考点自查：中国特色社会主义法治体系包括哪几个子体系？','建设中国特色社会主义法治体系，是全面依法治国的总抓手。它由五个子体系构成：①完备的法律规范体系——科学立法、提高立法质量；②高效的法治实施体系——严格执法、公正司法、全民守法；③严密的法治监督体系——加强对权力运行的制约和监督；④有力的法治保障体系——人才、经费、制度等保障；⑤完善的党内法规体系——依规治党与依法治国相结合。五个子体系相互衔接、支撑，构成法治建设的总体框架。','- “法治体系就是法律体系”❌（法治体系是“法律规范＋实施＋监督＋保障＋党内法规”的完整系统，内涵比法律体系更丰富）\n-  “法律越多越好”❌（良法是善治之前提，关键在质量）','全面依法治国'],
  ['4','必修3高频考点自查：如何辨析“依法治国”与“以德治国”的关系？','依法治国与以德治国相结合，是中国特色社会主义法治道路的鲜明特色。法律是成文的道德，道德是内心的法律——二者相辅相成、相得益彰。国家治理需要法律和道德协同发力：以法治体现道德理念，强化法律对道德建设的促进作用；以道德滋养法治精神，强化道德对法治文化的支撑作用。法治是他律，德治是自律，二者不能相互替代，也不能偏废其一。','- “法治与德治互相对立”❌（相辅相成、相得益彰）\n-  “以德治国就是用道德代替法律”❌（德法并举，各司其职）','全面依法治国'],
  ['5','必修3高频考点自查：法治国家、法治政府、法治社会一体建设如何理解？','坚持依法治国、依法执政、依法行政共同推进，坚持法治国家、法治政府、法治社会一体建设，是全面依法治国的顶层设计。法治国家是法治建设的目标——国家各项工作都实现制度化、法律化；法治政府是建设法治国家的重点任务和主体工程——政府依法行政，是全面依法治国中最关键、最直接的部分；法治社会是构筑法治国家的基础——全民尊法守法，法治观念深入人心。三者一体推进，形成上下贯通、协同发力的法治建设格局。','- “法治政府建设是法治社会的事”❌（法治政府是法治国家的重点任务和主体工程）\n-  “一体建设可以各管一段、分头推进”❌（必须统筹推进、形成合力）','全面依法治国'],
  ['6','必修3高频考点自查：从“五四宪法”到民法典——新中国法治进程有哪些标志性事件？','新中国法治进程的标志性事件：1954年一届全国人大一次会议通过第一部《中华人民共和国宪法》（“五四宪法”），奠定社会主义法治的基石；1982年五届全国人大五次会议通过现行宪法，此后历经五次修正；1999年“依法治国”入宪；2011年中国特色社会主义法律体系宣告形成；2020年十三届全国人大三次会议通过《中华人民共和国民法典》，是新中国第一部以“法典”命名的法律。这些事件见证了法治中国建设的坚实步伐。','- “民法典是新中国第一部法律”❌（新中国第一部法律是1950年《婚姻法》；民法典是第一部以“法典”命名的法律）\n-  “五四宪法是现行宪法”❌（现行宪法是1982年宪法）','全面依法治国']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'全面依法治国的总目标是（　）\nA. 建设法治政府　B. 建设中国特色社会主义法治体系、建设社会主义法治国家　C. 建设法治社会　D. 全面贯彻实施宪法', ans:'B。总目标是建设中国特色社会主义法治体系、建设社会主义法治国家；法治政府是重点任务和主体工程。' },
  { type:'配对 · 地位对应', body:'将十六字方针各环节与其地位配对：① 科学立法　② 严格执法　③ 公正司法　④ 全民守法\nA. 前提　B. 关键　C. 维护社会公平正义的最后一道防线　D. 基础', ans:'①-A　②-B　③-C　④-D' },
  { type:'图表排序 · 时序判断', body:'按时间先后排列：① 党的十五大确立依法治国基本方略　② “依法治国”写入宪法　③ 党的十八届四中全会专题研究全面依法治国　④ 民法典颁布施行', ans:'①→②→③→④。十五大（1997年）→宪法修正案（1999年）→十八届四中全会（2014年）→民法典通过（2020年）。' },
  { type:'材料解析 · 说明＋论证', body:'材料：“全面依法治国是国家治理的一场深刻革命，关系党执政兴国，关系人民幸福安康，关系党和国家长治久安。”\n问题：（1）为什么说全面依法治国是“一场深刻革命”？（4分）（2）结合材料，说明如何坚持依法治国、依法执政、依法行政共同推进。（4分）', ans:'（1）因为它推动国家治理从主要依靠政策转向主要依靠法治，实现治理理念、治理方式、治理体系的深刻变革（4分）。（2）依法治国是基本方略，依法执政是执政方式，依法行政是行政准则；三者共同推进，关键是党领导立法、保证执法、支持司法、带头守法（4分）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'结合法治国家、法治政府、法治社会一体建设，谈谈新时代青年如何为法治中国建设贡献力量。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只泛谈守法，未结合一体建设。\n· 辩证两维（4~6分）：结合法治国家、法治政府、法治社会一体建设，说明青年尊法学法守法用法的具体做法（依法维权、参与普法、监督违法）。\n· 综合升华（7~8分）：落到“法治中国建设人人有责，青年是法治建设的主力军，以青春之我建设法治中国”的规律性认识。' }
  ]
};
DATA.politics['侵权责任'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'法律常识体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'走在楼下被高空坠物砸伤，找谁赔？被邻居的狗咬伤，谁担责？——侵权责任，是权利受到侵害后的法律救济。' },
  { lead:false,text:'侵权责任的含义：行为人侵害他人合法权益依法应承担的法律责任（\'有侵害必有责任，有损害必有救济\'）。' },
  { lead:false,text:'归责原则（确定责任归属的准则）：<br>①过错责任原则——行为人主观上有过错（故意或过失）才承担责任：一般侵权适用，\'谁主张谁举证\'（被侵权人证明对方有过错）；<br>②过错推定责任原则——法律推定行为人有过错，行为人须自证无过错才能免责（举证责任倒置）：高空抛物（难以确定侵权人的，可能加害的建筑物使用人补偿——能证明自己不是侵权人的除外）、建筑物搁置物坠落、动物园动物致害；<br>③无过错责任原则——不论有无过错都要承担责任：高度危险作业（高压电、易燃易爆）、饲养动物致害（但能证明损害是因被侵权人故意或重大过失造成的，可减轻或不承担）、环境污染、产品缺陷致害。' },
  { lead:false,text:'承担侵权责任的方式（民法典列举八种）：停止侵害、排除妨碍、消除危险、返还财产、恢复原状、赔偿损失、赔礼道歉、消除影响恢复名誉。' },
  { lead:false,text:'典型案例：<br>①高空抛物——\'头顶上的安全\'：侵权人担责；找不到侵权人，可能加害者补偿（民法典第1254条，公安查清）；<br>②饲养动物——饲养人或管理人无过错责任（遛狗不拴绳致人损害要赔）；<br>③网络侵权——\'通知—删除\'规则（平台接到通知不处理要担责）。' },
  { lead:false,text:'\'侵权责任法守护的是：你的权利不容侵犯\'。<br>补充说明：本考点在近三年上海等级考中属高频内容，复习时务必结合案例与辨析要点。' }
  ],
  cards:[
  ['1','侵权责任有哪些承担方式？','承担方式（民法典八种）：①停止侵害；②排除妨碍；③消除危险；④返还财产；⑤恢复原状；⑥赔偿损失（最主要）；⑦赔礼道歉；⑧消除影响、恢复名誉。选择：可以单独适用，也可以合并适用（\'该停就停、该赔就赔、该道歉就道歉\'）。\'救济方式与损害类型匹配\'。','- \'侵权责任只有赔偿\'❌（八种方式，按需适用）\n-  \'赔礼道歉没有法律意义\'❌（是法定责任方式，具强制力）','法律常识'],
  ['2','过错责任原则怎样适用？','过错责任：行为人因过错侵害他人权益才承担责任——\'无过错则无责任\'。构成要件：①行为违法（侵害）；②损害事实；③因果关系；④主观过错（故意或过失）。举证：\'谁主张，谁举证\'——被侵权人须证明行为人有过错。适用范围：一般侵权（如普通人身伤害、财产损害）。\'过错是责任的伦理基础\'。','- \'过错责任不需要证明过错\'❌（一般侵权：谁主张谁举证）\n-  \'无过错就无任何责任\'❌（无过错责任情形除外，另有公平责任分担）','法律常识'],
  ['3','过错推定责任怎样适用？','过错推定责任：法律推定行为人有过错——行为人必须自证无过错才能免责（\'举证责任倒置\'：被告自证清白）。适用情形：①高空抛物（难以确定侵权人的，可能加害者补偿）；②建筑物、构筑物或其他设施及其搁置物、悬挂物脱落坠落致害；③动物园动物致害；④堆放物倒塌、林木折断致害。\'法律为什么推定？——受害人难以举证，推定保护弱者\'。','- \'过错推定＝无过错责任\'❌（推定可推翻，无过错责任不可推翻）\n-  \'高空抛物一律全体住户赔偿\'❌（能证明自己不是侵权人的除外）','法律常识'],
  ['4','无过错责任怎样适用？','无过错责任：不论行为人有无过错，只要行为与损害有因果关系就要担责（\'不问过错，只看因果\'）。适用情形：①高度危险作业（高压电、易燃易爆、高速轨道运输）；②饲养动物致害；③环境污染；④产品缺陷致害；⑤用人单位工作人员致害（用人单位担责）。免责事由严格：如能证明损害是受害人故意（重大过失）造成的，可减轻或不承担责任。\'危险源管控是核心理由\'。','- \'无过错责任就是绝对责任\'❌（有法定免责事由）\n-  \'饲养动物致害受害人有过错可全免\'❌（故意可减轻或免除，重大过失减轻）','法律常识'],
  ['5','网络侵权怎样治理？','网络侵权治理（\'通知—删除\'规则）：①权利人通知——被侵权人通知网络服务提供者（平台）删除侵权内容并提供初步证据；②平台处理——接到通知后及时采取删除、屏蔽、断开链接等必要措施；③责任划分——及时处理：平台免责；未及时处理：对损害扩大部分与侵权用户承担连带责任。另：\'反通知\'制度——被投诉用户可提交不存在侵权的声明。\'平台有守门人责任\'。','- \'平台对用户内容一律担责\'❌（及时处理可免责）\n-  \'通知删除是平台主动审查义务\'❌（是\'通知后\'的义务，除知道或应知情形）','法律常识'],
  ['6','侵权责任认识的规律是什么？','规律总结：①归责梯度——过错→过错推定→无过错，责任强度递增（对应举证难度与危险程度）；②救济多元——八种责任方式按需组合；③公平导向——举证倒置、补偿机制保护弱者（\'让受害者不孤单\'）；④预防功能——侵权责任吓阻危险行为（\'高空抛物入刑\'的警示）。\'侵权法：救济受害者、约束行为人\'。','- \'三种归责原则可以混用\'❌（法定情形对应法定原则）\n-  \'侵权责任只有事后救济\'❌（预防功能同样重要）','法律常识']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'饲养的动物致人损害，适用（　）\nA. 过错责任　B. 无过错责任　C. 过错推定责任　D. 公平责任', ans:'B。饲养动物致害适用无过错责任——不论饲养人有无过错都要担责。' },
  { type:'配对 · 时空定位', body:'将情形与归责原则配对：① 一般侵权　② 高空抛物　③ 环境污染　④ 产品缺陷\nA. 过错责任　B. 过错推定　C. 无过错责任　D. 无过错责任', ans:'①-A　②-B　③-C　④-D' },
  { type:'图表排序 · 读图分析', body:'按侵权责任分析步骤排列：① 确定归责原则　② 认定侵权事实　③ 确定责任方式', ans:'②→①→③。事实→原则→方式。' },
  { type:'材料解析 · 读图分析＋综合', body:'材料：某小区住户的花盆从阳台坠落砸坏楼下汽车，难以确定是哪户所为。\n问题：（1）该情形适用什么归责原则？（3分）（2）车主的损失如何救济？（3分）', ans:'（1）过错推定责任——难以确定具体侵权人的，由可能加害的建筑物使用人给予补偿（能证明自己不是侵权人的除外）（3分）。（2）救济：可请求可能加害的住户补偿；公安等机关应依法及时调查查清责任人；查明后由侵权人承担责任（3分）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'\'侵权责任制度是权利保护的最后一公里。\'结合归责原则，谈谈你的认识。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只谈一种归责原则。\n· 辩证两维（4~6分）：三种归责原则（过错、过错推定、无过错）的区分与适用，各举实例。\n· 综合升华（7~8分）：落到\'归责原则的梯度设计兼顾公平与救济——让受害者得到救济、让危险源被管控\'的规律性认识。' }
  ]
};
DATA.politics['党的领导'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'政治与法治体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'为什么说党的领导是中国特色社会主义最本质的特征？' },
  { lead:false,text:'①从历史看：中国共产党领导中国人民取得新民主主义革命胜利，建立新中国；完成社会主义革命，确立社会主义基本制度；进行改革开放新的伟大革命，开创中国特色社会主义。坚持党的领导是历史和人民的选择。' },
  { lead:false,text:'②从地位看：党是最高政治领导力量，处在总揽全局、协调各方的领导核心地位。党政军民学，东西南北中，党是领导一切的。' },
  { lead:false,text:'③从内容看：党的领导方式包括政治领导——制定和执行正确的路线、方针、政策；思想领导——用科学理论武装全党、教育人民；组织领导——推荐重要干部，发挥党组织的战斗堡垒作用和党员的先锋模范作用。' },
  { lead:false,text:'④从方式看：中国共产党坚持科学执政、民主执政、依法执政。依法执政是中国共产党执政的基本方式，党必须在宪法和法律范围内活动。' },
  { lead:false,text:'⑤从保障看：坚持党的领导、人民当家作主、依法治国有机统一于我国社会主义民主政治实践。党的领导是人民当家作主和依法治国的根本保证。' },
  { lead:false,text:'⑥从要求看：全面从严治党，勇于自我革命，是党跳出治乱兴衰历史周期率的第二个答案。党的初心和使命是为中国人民谋幸福、为中华民族谋复兴。' },
  { lead:false,text:'⚠️ 易错点：<br>- 党的最大优势是“一党制”❌（我国是新型政党制度而非一党制；最大优势是党的领导）<br>- 依法执政意味着党可以置身法律之外❌（党必须在宪法和法律范围内活动）<br>- 党的领导就是包办一切、代替国家机关❌（党总揽全局、协调各方，不直接行使国家权力）<br>备考提示：本考点在等级考中处于核心地位。答题时注意：①“最本质特征”“最大优势”的规范表述——中国共产党领导是中国特色社会主义最本质特征，是中国特色社会主义制度的最大优势；②党的初心使命——为中国人民谋幸福、为中华民族谋复兴；③坚持党的领导的“三个统一”——坚持党的领导、人民当家作主、依法治国有机统一。易错表述集中在把党的领导理解为包办代替、把依法执政混同于依法行政。归纳记忆：性质宗旨定立场，三种领导明方式，三种执政讲方式，从严治党保方向。考法上常以党的会议文件为材料，考查党的领导方式与执政方式的区别。' }
  ],
  cards:[
  ['1','中国共产党的性质与宗旨是什么？为什么说党没有任何自己特殊的利益？','中国共产党的性质：中国工人阶级的先锋队，中国人民和中华民族的先锋队。根本宗旨：全心全意为人民服务。党的立场：人民立场。党的性质决定了党除了工人阶级和最广大人民的根本利益，没有自己特殊的利益。党把实现好、维护好、发展好最广大人民的根本利益作为一切工作的出发点和落脚点。复习时建议结合制度内涵与典型案例对照记忆。','- “党有自己特殊的利益”❌\n-  “党的宗旨是共同富裕”❌（共同富裕是社会主义本质要求，党的宗旨是全心全意为人民服务）\n考试角度：党的性质决定宗旨，宗旨体现性质，二者统一于人民立场。答题时先答性质与宗旨，再落到人民立场。','政治与法治'],
  ['2','近代以来无数政治力量都失败了——历史和人民为什么最终选择了中国共产党？','近代中国，农民阶级、地主阶级洋务派、资产阶级改良派和革命派的各种救国方案都以失败告终。中国共产党把马克思主义基本原理同中国具体实际相结合，领导新民主主义革命取得胜利，建立了新中国；完成社会主义革命，确立社会主义基本制度；进行改革开放，开创中国特色社会主义。党的奋斗深刻改变了中华民族发展的方向和进程，深刻改变了中国人民和中华民族的前途命运。','- “选择党的领导是偶然的”❌\n-  “党只需要领导革命，不需要领导建设”❌（革命、建设、改革都离不开党的领导）\n答题角度：从近代救国探索失败、党的历史成就、三个深刻改变三个层次组织答案。结论落到“历史和人民的选择”。','政治与法治'],
  ['3','什么是党的政治领导、思想领导、组织领导？三者各通过什么途径实现？','政治领导：党制定和执行正确的路线、方针、政策，把握政治方向，是党的领导的首要方式；思想领导：用马克思主义中国化时代化的科学理论武装全党、教育人民，统一思想、凝聚共识；组织领导：向国家机关推荐重要干部，发挥党组织的战斗堡垒作用和党员的先锋模范作用。三者相互联系：政治领导是根本，思想领导是灵魂，组织领导是保证。','- “思想领导就是发文件”❌（核心是理论武装与思想引导）\n-  “三种领导方式互不相干”❌（三者统一于党的领导实践）\n考试角度：材料出现“制定政策”对应政治领导，“理论学习”对应思想领导，“干部推荐”对应组织领导。三者统一于党的领导实践。','政治与法治'],
  ['4','有人认为“党领导一切”会妨碍依法治国——坚持党的领导与依法治国真的冲突吗？','二者不冲突，而是有机统一。在我国社会主义民主政治实践中，党的领导是人民当家作主和依法治国的根本保证，人民当家作主是社会主义民主政治的本质特征，依法治国是党领导人民治理国家的基本方式。党领导人民制定宪法法律、领导人民实施宪法法律，党自身在宪法和法律范围内活动——坚持党的领导与依法治国高度一致。','- “三者统一等于三者并列、没有主次”❌（党的领导是根本保证，居统领地位）\n-  “党领导一切就可以超越法律”❌（党必须在宪法和法律范围内活动）\n高频设问：党的领导、人民当家作主、依法治国三者的关系。答题要点：根本保证、本质特征、基本方式，有机统一于社会主义民主政治实践。','政治与法治'],
  ['5','党的科学执政、民主执政、依法执政，三者各自的内涵与相互关系是怎样的？','科学执政：遵循共产党执政规律、社会主义建设规律、人类社会发展规律，按客观规律科学决策，是基本前提；民主执政：坚持为人民执政、靠人民执政，发展全过程人民民主，是本质所在；依法执政：党领导立法、带头守法，在宪法和法律范围内活动，是基本方式。三者相互联系、相互贯通，统一于党的执政实践，核心是坚持党的领导。','- “依法执政就是依法行政”❌（主体不同：依法执政主体是党，依法行政主体是政府）\n-  “科学执政只讲自然科学规律”❌（讲的是共产党执政规律、社会主义建设规律、人类社会发展规律）','政治与法治'],
  ['6','党的十八大以来，全面从严治党为何被称为“新时代党的自我革命的伟大实践”？','全面从严治党是“四个全面”战略布局的重要组成部分，是推进党的建设新的伟大工程的必然要求。党的十八大以来，党中央以“打虎”“拍蝇”“猎狐”惩治腐败，反腐败斗争取得压倒性胜利并全面巩固；出台中央八项规定，纠治“四风”；推动党内法规制度建设。自我革命是党跳出治乱兴衰历史周期率的第二个答案，全面从严治党永远在路上。','- “全面从严治党只是反腐败”❌（是党的建设整体要求）\n-  “从严治党是权宜之计”❌（永远在路上，长期任务）\n记忆要点：第一个答案——人民监督；第二个答案——自我革命。二者相互贯通，护航党长期执政。全面从严治党永远在路上。','政治与法治']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'中国特色社会主义最本质的特征是（　）\nA. 中国共产党领导　B. 依法治国　C. 人民当家作主　D. 生产资料公有制', ans:'A。中国共产党领导是中国特色社会主义最本质的特征，是中国特色社会主义制度的最大优势。' },
  { type:'配对 · 方式对应', body:'将党的领导方式与表现配对：① 政治领导　② 思想领导　③ 组织领导\nA. 推荐重要干部人选　B. 制定党的路线方针政策　C. 开展党的创新理论学习教育', ans:'①-B　②-C　③-A' },
  { type:'图表排序 · 时序判断', body:'按历史进程排序：① 中国共产党成立　② 新民主主义革命胜利　③ 社会主义基本制度确立　④ 中国特色社会主义进入新时代', ans:'①→②→③→④。1921年建党→1949年新中国成立→1956年社会主义改造基本完成→2017年十九大宣告进入新时代。' },
  { type:'材料解析 · 依据说明＋论证', body:'材料：党政军民学，东西南北中，党是领导一切的。\n问题：（1）为什么说党是最高政治领导力量？（4分）（2）说明中国共产党怎样通过依法执政实现对国家生活的领导。（4分）', ans:'（1）中国共产党是执政党，是中国特色社会主义事业的领导核心，党的领导是中国特色社会主义最本质的特征和最大优势（4分）。（2）党坚持依法执政，领导立法、保证执法、支持司法、带头守法，在宪法和法律范围内活动，把党的主张通过法定程序转化为国家意志（4分）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'有人说“党是领导一切的，所以党可以直接指挥政府机关”。运用党的领导的知识，谈谈你的理解。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只提党的领导或国家机关其一，无关联。\n· 辩证两维（4~6分）：说明党总揽全局、协调各方，通过政治领导、思想领导、组织领导实现领导，依法执政，不直接行使国家权力。\n· 综合升华（7~8分）：落到“坚持党的领导、人民当家作主、依法治国有机统一”的规律性认识。' }
  ]
};
DATA.politics['全民守法'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'全面依法治国体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'全民守法是法治的基础。法律要发生作用，首先全社会要信仰法律——人民群众对法律的真诚信仰，是法治的力量之源。' },
  { lead:false,text:'【基本要求】①尊法——尊崇法治、敬畏法律，把宪法法律铭刻在内心深处；②学法——学习法律知识，增强法治意识；③守法——依法行使权利，自觉履行义务，法律红线不可逾越；④用法——学会运用法律武器维护自身合法权益，做社会主义法治的忠实崇尚者、自觉遵守者、坚定捍卫者。' },
  { lead:false,text:'【法治理念】树立宪法法律至上理念——宪法法律具有最高权威，任何组织和个人都必须在宪法法律范围内活动；坚持法律面前人人平等——任何组织和个人都没有超越宪法法律的特权。' },
  { lead:false,text:'【法治习惯】养成“办事依法、遇事找法、解决问题用法、化解矛盾靠法”的法治习惯：办事依法，按规矩办、按法律办；遇事找法，不找关系、不托人情；解决问题用法，依法理性表达诉求；化解矛盾靠法，不信谣、不闹访。' },
  { lead:false,text:'【法治社会】建设法治社会，是构筑法治国家的基础。加强法治宣传教育，实施“八五”普法，把法治教育纳入国民教育体系；建设覆盖城乡的公共法律服务体系；健全社会矛盾纠纷预防化解机制，坚持和发展新时代“枫桥经验”。' },
  { lead:false,text:'【人人有责】全民守法，领导干部要带头守法——“其身正，不令而行”；公民既要自觉守法，也要敢于同违法行为作斗争，依法行使监督权。' },
  { lead:false,text:'⚠️ 易错点：<br>- 全民守法就是“老百姓守法”❌（一切组织和个人包括国家机关、领导干部都要守法）<br>- 守法就是消极“不违法”❌（还要主动尊法、用法、护法，敢于同违法行为作斗争）<br>- 法律面前人人平等只约束公民❌（任何组织和个人都不得有超越宪法法律的特权）<br>补充说明：全民守法的答题框架：要求（尊法学法守法用法）＋理念（宪法法律至上、法律面前人人平等）＋法治习惯（办事依法、遇事找法）＋法治社会建设。' }
  ],
  cards:[
  ['1','必修3高频考点自查：全民守法的“尊法、学法、守法、用法”四字诀，各自指什么？','全民守法要求全体社会成员尊法、学法、守法、用法：尊法——尊崇法治、敬畏法律，树立宪法法律至上理念；学法——学习宪法和法律法规，增强法治意识；守法——依法行使权利、自觉履行义务，不触碰法律红线；用法——运用法律武器维护自身合法权益，依法理性表达诉求。四者层层递进：尊法是前提，学法是基础，守法是关键，用法是目的。','- “尊法就是遵法”❌（尊法强调内心信仰，层次更高）\n-  “学法只是学生的事”❌（全民终身学法）','全面依法治国'],
  ['2','必修3高频考点自查：为什么说“人民群众对法律的真诚信仰”是全面依法治国的力量之源？','法治的力量不仅在于法律的强制力，更在于人民的内心拥护和真诚信仰。如果群众不信法、不靠法，遇事找关系、托人情，法律再多也形同虚设。全民守法的深层基础是法律信仰：相信法律能维护公平正义，愿意依法办事、依法维权。因此，要增强全民法治观念，加强法治文化建设，让尊法守法成为全社会的共同追求和自觉行动。这是法治建设的深层根基所在。','- “法治靠强制就够了”❌（没有信仰的强制难以持久）\n-  “法律信仰是天生的”❌（靠长期实践培育）','全面依法治国'],
  ['3','必修3高频考点自查：从“一五”普法到“八五”普法，全民普法经历了怎样的历程？','1986年起我国实施全民普法规划，每五年一个周期，至2021年已进入“八五”普法（2021—2025年）。普法是推进全民守法的基础工程。历程：“一五”普法（1986—1990）扫除法盲、普及法律常识；“四五”普法提出“两个转变、两个提高”；“七五”普法突出领导干部和青少年两个重点对象；“八五”普法要求提高普法针对性实效性，推进智慧普法。2023年12月4日是第十个国家宪法日。','- “国家宪法日是12月5日”❌（12月4日，“八二宪法”实施日）\n-  “普法只是司法机关的事”❌（谁执法谁普法，全社会共同责任）','全面依法治国'],
  ['4','有人说“守法就是不违法”——这种说法对吗？全民守法的完整内涵是什么？','这一说法不完整。守法当然要求不违法——依法行使权利、自觉履行义务；但全民守法的内涵更丰富：①守法——遵守法律，不触碰红线；②用法——运用法律维护自身合法权益；③护法——同违法行为作斗争，维护法律权威；④尊法——发自内心崇尚法治。消极“不违法”只是底线，主动尊法、用法、护法才是全民守法的完整要求，全社会都要做社会主义法治的忠实崇尚者、自觉遵守者、坚定捍卫者。','- “守法的义务主体只是普通公民”❌（一切组织和个人包括领导干部都要守法）','全面依法治国'],
  ['5','必修3高频考点自查：新时代“枫桥经验”的核心是什么？它与法治社会建设如何结合？','“枫桥经验”：20世纪60年代浙江诸暨枫桥干部群众创造的“发动和依靠群众，坚持矛盾不上交，就地解决”的经验。新时代“枫桥经验”的核心：矛盾不上交、平安不出事、服务不缺位，坚持自治、法治、德治相结合。与法治社会建设的结合：健全矛盾纠纷化解机制，人民调解、行政调解、司法调解联动，把矛盾化解在基层、化解在萌芽状态。','- “枫桥经验就是和稀泥”❌（依法调解、依法化解）\n-  “枫桥经验只适用于农村”❌（城市社区、企业同样适用）','全面依法治国'],
  ['6','必修3高频考点自查：12月4日国家宪法日与宪法宣誓制度——它们的设立有何意义？','2014年11月1日，全国人大常委会决定将12月4日设立为国家宪法日；2018年宪法修正案确立宪法宣誓制度——国家工作人员就职时公开向宪法宣誓。意义：①彰显宪法权威，弘扬宪法精神；②增强国家工作人员宪法意识，促进依宪履职；③推动全民尊崇宪法、学习宪法、遵守宪法、维护宪法、运用宪法。宪法是国家的根本法，是治国安邦的总章程。','- “宪法宣誓是可有可无的形式”❌（是增强宪法意识的重要制度）\n-  “宪法日是12月10日”❌（12月10日是世界人权日）','全面依法治国']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'全面依法治国十六字方针中，居于基础地位的是（　）\nA. 科学立法　B. 严格执法　C. 公正司法　D. 全民守法', ans:'D。全民守法是法治国家、法治政府、法治社会建设的基础。' },
  { type:'配对 · 要求对应', body:'将全民守法的四个要求与表现配对：① 尊法　② 学法　③ 守法　④ 用法\nA. 学习法律知识、增强法治意识　B. 依法行使权利、自觉履行义务　C. 敬畏法律、崇尚法治　D. 依法维权、理性表达诉求', ans:'①-C　②-A　③-B　④-D' },
  { type:'图表排序 · 层级排序', body:'按矛盾纠纷化解途径由协商到裁决排序：① 提起诉讼　② 协商和解　③ 人民调解　④ 申请仲裁', ans:'②→③→④→①。协商和解→人民调解→仲裁→诉讼，遵循先协商后裁决、能调则调的原则。' },
  { type:'材料解析 · 说明＋论证', body:'材料：某社区设立法律服务站、聘请法律顾问，居民“办事依法、遇事找法”，矛盾纠纷就地化解率明显提高。\n问题：（1）材料体现了全民守法的哪些要求？（4分）（2）如何理解“法律面前人人平等”？（4分）', ans:'（1）体现学法、用法，养成办事依法、遇事找法、解决问题用法的法治习惯（4分）。（2）任何组织和个人都必须在宪法法律范围内活动，都没有超越宪法法律的特权，平等享有权利、平等履行义务（4分）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'结合“枫桥经验”，谈谈青少年如何做法治的忠实崇尚者、自觉遵守者、坚定捍卫者。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只提守法或学习法律知识。\n· 辩证两维（4~6分）：结合“枫桥经验”的矛盾化解理念，从尊法学法守法用法、参与基层治理实践两方面说明做法。\n· 综合升华（7~8分）：落到“法治信仰内化于心、外化于行，青少年是法治社会建设的新生力量”的规律性认识。' }
  ]
};
DATA.politics['全过程人民民主'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'政治与法治体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'全过程人民民主“全”在哪里？' },
  { lead:false,text:'①提出过程：2019年11月，习近平在上海虹桥街道考察基层立法联系点时首次提出“人民民主是一种全过程的民主”。2021年中央人大工作会议系统阐述全过程人民民主重大理念；党的二十大报告将“发展全过程人民民主”作为中国式现代化的本质要求之一。' },
  { lead:false,text:'②内涵：全过程人民民主是社会主义民主政治的本质属性，是全链条、全方位、全覆盖的民主。“全链条”——民主选举、民主协商、民主决策、民主管理、民主监督各环节相互贯通；“全方位”——贯通国家政治生活和社会生活的各领域各方面；“全覆盖”——覆盖全体人民。' },
  { lead:false,text:'③三大特点：最广泛——参与主体最广、权利内容最广；最真实——人民当家作主有制度体系、法律保障和实践依托；最管用——能够有效避免西方选举民主“投票时受宠、选举后受冷”的弊端，真正解决人民要解决的问题。' },
  { lead:false,text:'④制度载体：人民代表大会制度（根本政治制度），中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度（基本政治制度），共同构成全过程人民民主的制度支撑。' },
  { lead:false,text:'⑤与西方民主的对比：全过程人民民主不仅有完整的制度程序，而且有完整的参与实践；不仅有选举权，更有决策、管理、监督各环节的参与权。' },
  { lead:false,text:'⚠️ 易错点：<br>- 全过程人民民主就是“选举民主的延伸”❌（是覆盖全链条的民主形态，选举只是其中一个环节）<br>- 全过程人民民主等于“直接民主”❌（是直接民主与间接民主的有机结合）<br>- 我国民主与西方民主只是形式差异❌（本质不同：人民当家作主与资产阶级统治）<br>备考提示：本考点是2022年以来等级考高频考点。答题时注意：①规范表述——全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主；②“全链条、全方位、全覆盖”三组词对应环节、领域、主体；③制度载体——一项根本政治制度加三项基本政治制度；④典型事例——基层立法联系点、人大“开门立法”、社区议事会、人大代表联络站。易错提醒：全过程人民民主不是选举民主的简单延伸，而是贯通各环节的民主形态。' }
  ],
  cards:[
  ['1','“人民民主是一种全过程的民主”——这一重大理念是怎样提出和发展的？','2019年11月，习近平在上海虹桥街道考察全国人大常委会基层立法联系点时首次提出“人民民主是一种全过程的民主”；2021年中央人大工作会议系统阐述全过程人民民主重大理念；2022年党的二十大报告明确“全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主”，并把发展全过程人民民主作为中国式现代化的本质要求之一。','- “全过程人民民主是党的二十大首次提出的”❌（2019年首次提出）\n-  “全过程人民民主只属于人大制度范畴”❌（贯通各制度各领域）\n习近平强调“人民民主是一种全过程的民主”，此后这一理念上升为党的二十大报告的重大部署，成为发展社会主义民主政治的行动指南。','政治与法治'],
  ['2','为什么要发展全过程人民民主？为什么说它是中国式现代化的本质要求？','我国是人民民主专政的社会主义国家，人民当家作主是社会主义民主政治的本质和核心。发展全过程人民民主是坚持人民主体地位的必然要求，是中国式现代化的本质要求之一，有利于保障人民权益、激发人民创造活力，推进国家治理体系和治理能力现代化。复习时建议结合制度内涵与典型案例对照记忆。等级考中常以选择题或材料题形式考查这一内容。','- “民主只是手段不是目的”❌（人民当家作主是目的与手段的统一）\n-  “现代化只是经济现代化”❌（还包括政治、社会等各领域现代化）\n中国式现代化是人口规模巨大的现代化，全过程人民民主是其中的政治文明标识，二者统一于中华民族伟大复兴实践。民主与现代化相互促进。','政治与法治'],
  ['3','民主选举、民主协商、民主决策、民主管理、民主监督，五个环节怎样衔接？','五个环节构成全链条：民主选举是基础环节，人民选出代表和公职人员；民主协商在决策前和决策实施中广泛商量；民主决策集中民意形成方案；民主管理依靠人民群众参与治理；民主监督保障各环节落实、纠偏。五环节环环相扣、彼此贯通，使民主贯穿国家治理全过程。复习时建议结合制度内涵与典型案例对照记忆。','- “五个环节彼此孤立”❌\n-  “民主监督只是事后监督”❌（是全程监督）\n答题提示：五个环节与“全链条”对应——选举产生代表、协商凝聚共识、决策形成方案、管理保障实施、监督纠偏改进。材料题中常要求按环节归类具体做法。全链条意味着民主不仅体现在投票时，更体现在日常治理中。','政治与法治'],
  ['4','全过程人民民主与西方“投票时受宠、选举后受冷”的选举民主有何不同？','西方选举民主主要体现为周期性投票，选举结束、民主“休眠”。全过程人民民主不仅有完整的制度程序，而且有完整的参与实践：人民在选举之后仍通过协商、决策、管理、监督持续参与，是全链条、全方位、全覆盖的民主，体现人民当家作主的本质。复习时建议结合制度内涵与典型案例对照记忆。等级考中常以选择题或材料题形式考查这一内容。','- “我国民主不需要选举”❌（选举是重要环节）\n-  “西方民主也是全过程民主”❌（本质不同，环节残缺）\n我国民主实现了过程民主与成果民主、程序民主与实质民主、直接民主与间接民主、人民民主与国家意志相统一。','政治与法治'],
  ['5','从主体、保障、实效三个维度看，怎样理解全过程人民民主“最广泛、最真实、最管用”？','最广泛——参与主体最广（全体人民）、参与领域最广（政治、经济、文化、社会各领域）；最真实——有根本政治制度和基本政治制度体系保障，有宪法法律保障，有实实在在的实践依托；最管用——坚持以人民为中心，聚焦解决人民“急难愁盼”问题，推动善治，避免议而不决、决而不行。复习时建议结合制度内涵与典型案例对照记忆。','- “最管用等于效率高”❌（是解决实际问题、实现善治）\n-  “三个特点可以相互替代”❌（各有所指，有机统一）\n全过程人民民主把“三个最”统一于一体：主体与权利的广泛、制度与法律的保障、问题与善治的实效。三者共同回答“中国的民主为什么好”。复习时可与基层立法联系点等实例对照理解。','政治与法治'],
  ['6','上海虹桥街道基层立法联系点的故事，怎样折射“全过程人民民主大气象”？','虹桥街道是全国人大常委会法工委首批基层立法联系点之一。群众“原汁原味”的意见建议直达国家立法机关，多部法律吸收采纳了来自“小巷”的声音。小小联系点成为开门立法、民主立法的窗口，说明全过程人民民主把立法大门开在群众家门口，人民的声音能够转化为国家意志。复习时建议结合制度内涵与典型案例对照记忆。','- “立法是专家的事，与群众无关”❌\n-  “联系点的意见只是参考、可有可无”❌（合理意见被吸收采纳，有反馈机制）\n虹桥经验：立法信息员队伍、圆桌会议、意见反馈单，形成“收集—吸纳—反馈”闭环，让立法工作看得见、摸得着、有回应。基层立法联系点已遍布全国，是全过程人民民主的生动缩影。','政治与法治']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'全过程人民民主“最管用”是指（　）\nA. 参与主体广泛　B. 有制度保障　C. 解决实际问题、促进善治　D. 环节多', ans:'C。“最管用”指民主不是装饰品，而是用来解决人民要解决的问题。' },
  { type:'配对 · 特点对应', body:'将“三个最”与内涵配对：① 最广泛　② 最真实　③ 最管用\nA. 有宪法法律和制度体系保障　B. 参与主体与权利内容广泛　C. 有效解决人民要解决的问题', ans:'①-B　②-A　③-C' },
  { type:'图表排序 · 流程判断', body:'按开门立法中全过程人民民主的运行流程排序：① 立法项目征集公众意见　② 法律草案向社会公开征求意见　③ 全国人大表决通过　④ 公布实施并接受监督', ans:'①→②→③→④。从立项、起草、审议到通过、实施，人民参与贯穿立法全链条。' },
  { type:'材料解析 · 案例分析＋论证', body:'材料：上海虹桥街道是全国人大常委会法工委首批基层立法联系点之一，群众“原汁原味”的意见建议直达国家立法机关，多部法律吸收采纳了来自“小巷”的声音。\n问题：（1）立法联系点体现了全过程人民民主的什么特点？（4分）（2）说明发展全过程人民民主的意义。（4分）', ans:'（1）体现全过程人民民主是最广泛、最真实、最管用的民主——群众意见直达立法机关并被采纳，民主有制度保障、能解决实际问题（4分）。（2）发展全过程人民民主有利于保障人民当家作主，激发人民创造活力，推进国家治理体系和治理能力现代化，是社会主义民主政治的本质属性（4分）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'有人认为“民主就是投票选举”。运用全过程人民民主的知识评析这一观点。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只提选举或民主其一，无关联。\n· 辩证两维（4~6分）：说明选举只是民主的一个环节，全过程人民民主贯通民主选举、民主协商、民主决策、民主管理、民主监督。\n· 综合升华（7~8分）：落到“全过程人民民主是最广泛、最真实、最管用的民主，是社会主义民主政治的本质属性”的规律性认识。' }
  ]
};
DATA.politics['公正司法'] = {
  status:'JSON 自动转换（2026-08-19）',
  tags:{ type:'全面依法治国体', headers:["#", "考点", "核心要点", "易混辨析", "角度"], source:'JSON 卡片自动转换' },
  body:[
  { lead:true,text:'司法是维护社会公平正义的最后一道防线。一次不公正的审判，其恶果甚至超过十次犯罪——因为犯罪污染的是水流，而不公正的审判污染的是水源。' },
  { lead:false,text:'【主体与职权】人民法院是国家的审判机关，依法独立行使审判权；人民检察院是国家的法律监督机关，依法独立行使检察权。司法机关独立行使职权，不受行政机关、社会团体和个人的干涉。' },
  { lead:false,text:'【基本原则】①以事实为根据、以法律为准绳；②法律面前人人平等——对任何人犯罪，在适用法律上一律平等；③实体公正与程序公正并重——实体公正指向裁判结果正确，程序公正指向诉讼过程正当，二者缺一不可。' },
  { lead:false,text:'【改革举措】深化司法体制改革：实行司法责任制，“让审理者裁判、由裁判者负责”；推进以审判为中心的诉讼制度改革；健全冤假错案防范和纠正机制；深化司法公开——审判流程公开、庭审公开、裁判文书公开、执行信息公开，以公开促公正、以透明保廉洁。' },
  { lead:false,text:'【根本目标】努力让人民群众在每一个司法案件中感受到公平正义。坚持司法为民——完善法律援助和司法救助制度，让困难群众打得起官司、打得好官司。' },
  { lead:false,text:'【与执法衔接】公正司法与严格执法相互衔接：行政机关的执法行为要接受司法审查，行政诉讼由人民法院审理裁判；人民法院生效裁判，行政机关必须尊重和执行。' },
  { lead:false,text:'⚠️ 易错点：<br>- 司法机关包括公安机关❌（公安机关是行政机关，司法机关是人民法院和人民检察院）<br>- 独立行使审判权意味着不受任何监督❌（要接受党的领导、人大监督、人民监督）<br>- 实体公正比程序公正重要❌（二者并重，程序公正是实体公正的保障）<br>补充说明：公正司法的答题框架：含义（以事实为根据、以法律为准绳）＋主体（人民法院行使审判权、人民检察院行使检察权）＋最后一道防线的地位＋司法责任制与司法公开。' }
  ],
  cards:[
  ['1','必修3高频考点自查：在我国，司法机关具体指哪些机关？它们各自的法定职权分别是什么？','我国的司法机关是人民法院和人民检察院。人民法院是国家的审判机关，依法独立行使审判权——通过审判刑事、民事、行政案件，惩罚犯罪、解决纠纷、保护合法权益。人民检察院是国家的法律监督机关，依法独立行使检察权——对侦查、审判、执行等活动进行法律监督，依法提起公诉。司法机关独立行使职权，不受行政机关、社会团体和个人的干涉。','- “公安机关是司法机关”❌（属于行政机关）\n-  “检察院是审判机关”❌（是法律监督机关）','全面依法治国'],
  ['2','培根说“一次不公正的审判，其恶果甚至超过十次犯罪”——这句话如何理解？','英国哲学家培根的名言揭示了司法公正的极端重要性：犯罪只是污染了水流，而不公正的审判则污染了水源。司法是维护社会公平正义的最后一道防线——公民的合法权益受到侵害后，最后的救济途径就是司法；如果司法不公，受到侵害的权利就无处伸张，社会正义就失去最终依托。冤错案件造成的伤害难以弥补，还会动摇人民群众对法治的信仰。','- “司法公正只是对当事人的事”❌（关系全社会公平正义的底线）\n-  “错案不可避免所以无须追责”❌（有错必纠、责任必究）','全面依法治国'],
  ['3','必修3高频考点自查：司法责任制改革如何落实“让审理者裁判、由裁判者负责”的要求？','司法责任制改革的核心：让审理者裁判、由裁判者负责。具体举措：①落实主审法官、合议庭办案责任制——谁审理、谁裁判、谁负责，院庭长不再签发未参加审理案件的裁判文书；②建立法官、检察官办案质量终身负责制和错案责任倒查问责制；③组建以法官为中心的审判团队，减少行政化审批环节。司法改革让司法去行政化，权责统一，倒逼人民法院依法独立行使审判权，实现公正司法。','- “司法责任制就是出了问题才追责”❌（核心是权责统一、保障独立办案）\n-  “终身负责制违反实事求是”❌（有错必纠、依法追责）','全面依法治国'],
  ['4','必修3高频考点自查：实体公正与程序公正到底哪个更重要？二者关系应当如何辨析？','实体公正，指裁判结果符合事实与法律，使应当保护的权益得到保护、应当惩罚的犯罪受到惩罚；程序公正，指诉讼过程严格依照法定程序进行，当事人依法享有平等参与的权利。二者关系：程序公正是实体公正的保障——公正的程序能最大限度查明事实；实体公正是程序公正的归宿。二者并重、不可偏废：只重实体，容易刑讯逼供、冤错频发；只重程序，可能“程序正确而结果不公”。','- “实体公正比程序公正重要”❌（二者并重）\n-  “程序公正只是走形式”❌（程序公正是看得见的正义，本身具有独立价值）','全面依法治国'],
  ['5','必修3高频考点自查：司法公开的“四大平台”具体指什么？司法公开如何促进公正司法？','司法公开“四大平台”：审判流程公开、庭审活动公开、裁判文书公开、执行信息公开。中国庭审公开网直播庭审，中国裁判文书网公开海量裁判文书，执行信息网公开执行进展——司法权力在阳光下运行。司法公开的意义：以公开促公正、以透明保廉洁，保障人民群众的知情权、参与权、监督权，倒逼法官提高裁判质量，提升司法公信力。','- “司法公开就是全部文书一律上网”❌（法定情形除外）\n-  “司法公开会干预独立审判”❌（公开与监督是独立公正的保障）','全面依法治国'],
  ['6','必修3高频考点自查：呼格吉勒图案、聂树斌案获依法平反，冤错案件纠正在法治上有何意义？','呼格吉勒图案：1996年当事人被执行死刑，2014年内蒙古高级人民法院再审宣告无罪；聂树斌案：2016年最高人民法院第二巡回法庭再审改判无罪。两案平反的意义：①彰显“实事求是、有错必纠”的司法原则；②体现疑罪从无、证据裁判的法治进步；③推动健全冤错案件防范纠正机制，落实办案质量终身负责制；④重塑公众对司法公正的信心，是公正司法在曲折中前行的见证。','- “冤错案件说明司法不可信”❌（有错必纠恰恰体现司法进步）\n-  “改判无罪等于当年办案人没有责任”❌（实行错案责任倒查问责）','全面依法治国']
  ],
  quiz:[
  { type:'单选 · 概念辨析', body:'我国的审判机关和法律监督机关分别是（　）\nA. 法院和公安机关　B. 人民法院和人民检察院　C. 人民检察院和人民法院　D. 监察委员会和法院', ans:'B。人民法院是审判机关，人民检察院是法律监督机关。' },
  { type:'配对 · 职权对应', body:'将司法机关与法定职权配对：① 人民法院　② 人民检察院\nA. 依法独立行使审判权　B. 依法独立行使检察权（法律监督权）', ans:'①-A　②-B' },
  { type:'图表排序 · 流程排序', body:'按民事诉讼一般流程先后排序：① 立案受理　② 起诉　③ 开庭审理　④ 判决　⑤ 执行', ans:'②→①→③→④→⑤。起诉→立案受理→开庭审理→判决→执行。' },
  { type:'材料解析 · 说明＋论证', body:'材料：呼格吉勒图案等重大冤错案件被依法纠正，相关办案人员被追究责任。\n问题：（1）纠正冤错案件体现了公正司法的哪些要求？（4分）（2）为什么说“司法是维护社会公平正义的最后一道防线”？（4分）', ans:'（1）体现以事实为根据、以法律为准绳，实体公正与程序公正并重，有错必纠、责任必究（4分）。（2）立法设定规则、执法执行规则之后，司法是解决纠纷、救济权利的最后环节；若司法不公，公平正义就失去最终保障（4分）。' },
  { type:'开放论述 · 评价论述（三层给分）', body:'结合司法公开改革，谈谈如何“努力让人民群众在每一个司法案件中感受到公平正义”。（8分）', ans:'评分标准（三层给分）：\n· 单一维度（1~3分）：只提司法公开或公平正义其一。\n· 辩证两维（4~6分）：结合审判流程、庭审、裁判文书、执行信息公开四大平台，说明以公开促公正、以透明保廉洁，并联系司法责任制。\n· 综合升华（7~8分）：落到“司法公正既要裁判结果公正，也要诉讼过程公正，让公平正义可感可触”的规律性认识。' }
  ]
};
